-- 5. Cadastrar contatos únicos (deduplicação por cliente + dígitos do telefone)
insert into contatos (cliente_id, nome, telefone, bairro, criado_em)
select distinct on (regexp_replace(telefone, '\D', '', 'g'))
  '9d17ae73-9c04-47fd-b0cf-3bb0e5c5b800'::uuid,
  nome,
  telefone,
  coalesce(trim(bairro), ''),
  (data_abertura::text || ' 12:00:00-03')::timestamptz
from tmp_leads_import
where regexp_replace(telefone, '\D', '', 'g') <> ''
order by regexp_replace(telefone, '\D', '', 'g'), data_abertura desc
on conflict (cliente_id, telefone_digitos) do update
set
  nome = case when contatos.nome in ('', '-', 'Sem nome') and excluded.nome not in ('', '-', 'Sem nome') then excluded.nome else contatos.nome end,
  bairro = case when contatos.bairro = '' and excluded.bairro <> '' then excluded.bairro else contatos.bairro end;

-- 6. Inserir todas as negociações vinculadas aos contatos gerados
insert into negociacoes (
  cliente_id,
  contato_id,
  data_abertura,
  ultima_interacao,
  servico,
  origem,
  status,
  valor_orcamento,
  valor_fechado,
  data_fechamento,
  motivo_perda,
  observacoes,
  tipo_cliente
)
select
  '9d17ae73-9c04-47fd-b0cf-3bb0e5c5b800'::uuid,
  c.id,
  t.data_abertura,
  t.ultima_interacao,
  t.servico,
  t.origem,
  t.status,
  t.valor_orcamento,
  t.valor_fechado,
  t.data_fechamento,
  t.motivo_perda,
  t.observacoes,
  'Novo'::tipo_cliente
from tmp_leads_import t
join contatos c on c.cliente_id = '9d17ae73-9c04-47fd-b0cf-3bb0e5c5b800'::uuid
               and c.telefone_digitos = regexp_replace(t.telefone, '\D', '', 'g')
order by t.row_id;

-- 7. Recalcular tipo_cliente (Novo, Recorrente, Reativação) para vendas fechadas
update negociacoes n
set tipo_cliente = case
  when prev.ultima_compra is null then 'Novo'::tipo_cliente
  when (n.data_fechamento - prev.ultima_compra) > 180 then 'Reativação'::tipo_cliente
  else 'Recorrente'::tipo_cliente
end
from (
  select
    n1.id,
    max(n2.data_fechamento) as ultima_compra
  from negociacoes n1
  left join negociacoes n2
    on n2.contato_id = n1.contato_id
   and n2.cliente_id = n1.cliente_id
   and n2.id <> n1.id
   and n2.status = 'Fechou'
   and n2.data_fechamento < n1.data_fechamento
  where n1.cliente_id = '9d17ae73-9c04-47fd-b0cf-3bb0e5c5b800'::uuid
    and n1.status = 'Fechou'
  group by n1.id
) prev
where n.id = prev.id;

-- 8. Reativar a trigger de integridade de regras de negócio
alter table negociacoes enable trigger trg_negociacoes_regras;

commit;
